body{
    font-family:Times New Roman;
    width:480px;
    padding:10px;
}

math-field {
    border: 1px solid #ccc;
    min-height: 100px;
    font-size: 24px;
    padding: 10px;
    margin-top: 5px;
    display: block;
    width: 100%;
    box-sizing: border-box;
}


#preview{
    border:1px solid #ddd;
    padding:10px;
    margin-top:5px;
    min-height:50px;
    background-color: #f9f9f9;
    position: relative;
}

#preview::after {
    content: "Preview";
    position: absolute;
    bottom: 5px;
    right: 5px;
    font-size: 12px;
    color: #666;
    font-weight: bold;
}

.buttons{
    margin-top:10px;

}

#exportBtn {
    font-family: Times New Roman;
    background-color: #4CAF50;
    color: white;
    border: none;
    text-align: center;
    text-decoration: none;
    display: inline-block;
    font-size: 16px;
    cursor: pointer;
    border-radius: 5px;
}

#clearBtn {
    font-family: Times New Roman;
    background-color: #f44336;
    color: white;
    border: none;
    text-align: center;
    text-decoration: none;
    display: inline-block;
    font-size: 16px;
    cursor: pointer;
    border-radius: 5px;
}
